window.AUTH=window.AUTH||{};window.AUTH["19-416"]={"d":"19-416","id":"2020/19-416","n":"Nestlé USA, Inc. v. Doe I","briefs":[{"k":"petitioner","label":"Brief of petitioner Nestlé USA, Inc.","date":"2020-08-31","url":"https://www.supremecourt.gov/DocketPDF/19/19-416/151727/20200831135559746_19-416%2019-453%20Nestle%20Opening%20Brief%208-31%20final.pdf","side":"pet","n":41},{"k":"petitioner","label":"Brief of petitioner Cargill, Inc.","date":"2020-08-31","url":"https://www.supremecourt.gov/DocketPDF/19/19-416/151732/20200831141439811_19-416%20-453%20Cargill%20Petitioner%20Brief.pdf","side":"pet","n":33},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2020-09-08","url":"https://www.supremecourt.gov/DocketPDF/19/19-416/153365/20200908144507659_19-416tsacUnitedStates.pdf","side":"us","n":24},{"k":"respondent","label":"Brief of respondents in 19-416 (response to merits brief of Nestle USA, Inc.)","date":"2020-10-14","url":"https://www.supremecourt.gov/DocketPDF/19/19-416/157704/20201014155852761_Nestle%20Revised%20Final%20Type%20A.pdf","side":"res","n":50},{"k":"respondent","label":"Brief of respondents in 19-453 (response to merits brief of Cargill, Inc.)","date":"2020-10-19","url":"https://www.supremecourt.gov/DocketPDF/19/19-416/158111/20201019144139703_Cargill%20Type%20A%20FInal.pdf","side":"res","n":51},{"k":"reply","label":"Reply of petitioner Nestlé USA, Inc.","date":"2020-11-13","url":"https://www.supremecourt.gov/DocketPDF/19/19-416/160607/20201113132927289_Nestle%20-%20Reply%20Brief%2011.13.20%20Final.pdf","side":"pet","n":24},{"k":"reply","label":"Reply of petitioner Cargill, Inc.","date":"2020-11-13","url":"https://www.supremecourt.gov/DocketPDF/19/19-416/160605/20201113132652149_19-416%20-453%20Cargill%20Reply%20Brief.pdf","side":"pet","n":24}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us2r48_p8k0.pdf","tr":true,"items":[{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"op":2,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"40","6":"1"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"0":"24","2":"33","6":"16, 17"}},{"t":"case","label":"Blue Chip Stamps v. Manor Drug Stores","cite":"421 U.S. 723","y":1975,"id":"1974/74-124","sc":1,"sum":"A private damages action under Rule 10b-5 is confined to actual purchasers or sellers of securities and the Birnbaum rule bars respondent from maintaining this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Bolchos v. Darrel","cite":"3 F. Cas. 810","y":1795,"court":"D.C.D.S.C.","url":"https://www.courtlistener.com/c/F.%20Cas./3/810/","by":{"0":"17"}},{"t":"case","label":"Bowoto v. Chevron Corp.","cite":"621 F.3d 1116","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/621/1116/","by":{"0":"48"}},{"t":"case","label":"Cent. Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"op":1,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"0":"23","1":"31","2":"8, 24, 25","6":"9, 22"}},{"t":"case","label":"Corr. Servs. Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"sum":"The Court held that Bivens' limited holding may not be extended to confer a right of action for damages against private entities acting under color of federal law. The Court reasoned that the threat of suit against an individual's employer was not the kind of deterrence contemplated by the Bivens decision.","sumSrc":"Oyez","by":{"0":"40, 50","1":"16, 20, 44, 45","2":"7, 14, 24"}},{"t":"case","label":"Doe VIII v. Exxon Mobil Corp.","cite":"654 F.3d 11","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/654/11/","op":1,"by":{"0":"passim","1":"15, 29, 37, 42, 47","2":"11, 15, 25","3":"36","4":"35","5":"8, 9, 19"}},{"t":"case","label":"EEOC v. Arabian Am. Oil Co.","cite":"499 U.S. 244","y":1991,"id":"1990/89-1838","sc":1,"sum":"Title VII does not apply extraterritorially to regulate the employment practices of United States firms that employ American citizens abroad. Petitioners' evidence, while not totally lacking in probative value, falls short of demonstrating the clearly expressed affirmative congressional intent that is required to overcome the well-established presumption against statutory extraterritoriality.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Elkins v. United States","cite":"364 U.S. 206","y":1960,"id":"1959/126","sc":1,"sum":"1. Evidence obtained by state officers during a search which, if conducted by federal officers, would have violated the defendant's immunity from unreasonable searches and seizures under the Fourth Amendment is inadmissible over the defendant's timely objection in a federal criminal trial, even when there was no participation by federal officers in the search and seizure.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49"}},{"t":"case","label":"F. Hoffmann-La Roche Ltd. v. Empagran S.A.","cite":"542 U.S. 155","y":2004,"id":"2003/03-724","sc":1,"op":23,"sum":"The Court unanimously ruled that Congress' intent in passing the FTAIA was to prevent American courts from interfering in foreign commerce. Congress made an exception for foreign commerce that affected domestic commerce, but the exception should not be read as a general prohibition against price-fixing in all parts of the world.","sumSrc":"Oyez","by":{"0":"20","3":"34","4":"34"}},{"t":"case","label":"Filartiga v. Pena–Irala","cite":"630 F.2d 876","y":1980,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/630/876/","by":{"0":"13","3":"2, 12, 17, 53, 2","4":"2, 12, 50, 2-3"}},{"t":"case","label":"Foley Bros. v. Filardo","cite":"336 U.S. 281","y":1949,"id":"scdb/1948-045","sc":1,"sum":"The Eight Hour Law, 40 U. S. C. § 324, as amended by 40 U. S. C. § 325a, which provides, in effect, that every contract to which the United States is a party shall contain a provision that no laborer or mechanic doing any part of the work contemplated by the contract shall be required or permitted to work more than eight hours in any one day upon such work unless he is compensated at the rate of one and one-half …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Jesner v. Arab Bank, PLC","cite":"138 S. Ct. 1386","y":2018,"id":"2017/16-499","sc":1,"op":24,"ar":26,"sum":"The Court held that the Alien Tort Statute does not permit lawsuits against corporations.","sumSrc":"Oyez","by":{"0":"passim","1":"2-4, 10, 14-17, 20, 21, 28, 36, 37, 40-50","2":"passim","3":"passim, 40, 42, 43, 44, 47, 46, 47","4":"passim, 38, 40, 41, 42, 45, 44-45","5":"passim","6":"5, 6, 17-23"}},{"t":"case","label":"Kiobel v. Royal Dutch Petroleum Co.","cite":"569 U.S. 108","y":2013,"id":"2011/10-1491","sc":1,"op":9,"sum":"The Court found that the Alien Tort Statute does not give ground for United States law to be applied extraterrestrially to other sovereign nations with their own laws.","sumSrc":"Oyez","by":{"0":"passim","1":"2, 3, 7, 9, 17-19, 22, 23, 26, 28, 29, 34-37, 40","2":"3, 11","3":"passim, 2, 27, 17","4":"passim, 2, 26","5":"passim","6":"3, 4, 5, 7, 11, 13, 15"}},{"t":"case","label":"Kiobel v. Royal Dutch Petroleum Co.","cite":"621 F.3d 111","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/621/111/","sum":"Concluding that jurisdiction of international tribunals is consistently limited to natural persons.","sumSrc":"brief:1","by":{"0":"37, 49, 50, 51","1":"15, 42, 43","4":"passim","5":"9, 18, 19","6":"18, 19"}},{"t":"case","label":"Khulumani v. Barclay Nat’l Bank Ltd.","cite":"504 F.3d 254","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/504/254/","op":1,"by":{"0":"22","2":"9, 15, 25, 28, 29","6":"10"}},{"t":"case","label":"Lujan v. Defs. of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"McMillian v. Monroe County","cite":"520 U.S. 781","y":1997,"id":"1996/96-542","sc":1,"sum":"The opinion by Chief Justice William Rehnquist held that because the county had no authority to make law enforcement policy, Sheriff Tate as a policymaker represented the state rather than the county. According to the Alabama Constitution and the Alabama Code, the Court held, Alabama sheriffs \"act for the State when exercising their law enforcement functions.\".","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Microsoft Corp. v. AT & T Corp.","cite":"550 U.S. 437","y":2007,"id":"2006/05-1056","sc":1,"sum":"The Court ruled 7-1 that Microsoft was not liable for infringement of AT&T's patent. The opinion by Justice Ruth Bader Ginsburg held that \"software code is an idea without physical embodiment\"; it cannot be a component of a patented invention.","sumSrc":"Oyez","by":{"0":"20","3":"26","4":"25","5":"6","6":"13"}},{"t":"case","label":"Mohamad v. Palestinian Auth.","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"sum":"The Court held that the word \"individual\" in the Torture Victim Protection Act means a natural person and does not impose any liability against organizations.","sumSrc":"Oyez","by":{"0":"43","3":"32, 52","4":"49"}},{"t":"case","label":"Morrison v. Nat’l Austl. Bank Ltd.","cite":"561 U.S. 247","y":2010,"id":"2009/08-1191","sc":1,"op":1,"ar":3,"sum":"The Court held that the Securities and Exchange Act does not provide a cause of action against foreign plaintiffs suing foreign and American defendants for misconduct in connection with securities traded on foreign stock exchanges.","sumSrc":"Oyez","by":{"0":"passim","1":"7, 9, 11, 13, 27, 28, 30, 32","2":"22, 26, 30, 31","3":"passim","4":"passim","6":"4, 5, 6, 7, 8"}},{"t":"case","label":"Moxon v. The Fanny","cite":"17 F. Cas. 942","y":1793,"court":"D.C.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Cas./17/942/","by":{"0":"17"}},{"t":"case","label":"Nestle U.S.A., Inc. v. Doe I","cite":"136 S. Ct. 798","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/798/","sc":1,"op":1,"ar":6,"by":{"0":"9"}},{"t":"case","label":"Presbyterian Church of Sudan v. Talisman Energy, Inc.","cite":"582 F.3d 244","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/582/244/","op":1,"by":{"0":"33","1":"38, 39"}},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"sum":"The plurality rejected the argument that only actually-navigable waters can be regulated by the Clean Water Act, but also held that the word \"navigable\" in the Act cannot be divested of all meaning. The plurality held that the definitional term \"waters of the United States\" can only refer to \"relatively permanent, standing or flowing bodies of water,\" not \"occasional,\" \"intermittent,\" or \"ephemeral\" flows.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"RJR Nabisco, Inc. v. European Cmty.","cite":"136 S. Ct. 2090","y":2016,"id":"2015/15-138","sc":1,"op":4,"ar":1,"sum":"The Court held that some sections of the Racketeer Influenced Corrupt Organizations (RICO) statute can apply extraterritorially because Congress clearly based them on predicate offenses that can occur outside of the United States.","sumSrc":"Oyez","by":{"0":"passim","1":"3, 9, 11, 17, 18, 21-23, 26, 27, 33","2":"4, 8, 22, 26, 32","3":"20, 21, 26","4":"20, 25","5":"passim","6":"4, 5, 9, 13"}},{"t":"case","label":"Silva v. Gonzales","cite":"2014 WL 12663140","y":2014,"court":"S.D. Cal. May 23","by":{"0":"45"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"op":51,"ar":20,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"0":"passim","1":"2, 3, 31, 36, 39-41, 43-45, 47","2":"passim","3":"passim","4":"passim","5":"passim","6":"1, 18, 19, 20"}},{"t":"case","label":"The Nurnberg Trial (United States v. Goering)","cite":"6 F.R.D. 69","y":1946,"court":"Int’l Military Trib. at Nuremberg","url":"https://www.courtlistener.com/c/F.R.D./6/69/","by":{"0":"50"}},{"t":"case","label":"Touche Ross & Co. v. Redington","cite":"442 U.S. 560","y":1979,"id":"1978/78-309","sc":1,"sum":"There is no implied private cause of action for damages under § 17 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Vill. of Arlington Heights v. Metro. Hous. Dev. Corp.","cite":"429 U.S. 252","y":1977,"id":"1976/75-616","sc":1,"sum":"After finding that MHDC had proper federal standing, since it acted on behalf of black plaintiffs who stood to suffer direct and measurable injuries from Arlington's denial, the Court held that it failed to establish Arlington's racially discriminatory intent or purpose.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"137 S. Ct. 1843","y":2017,"id":"2016/15-1358","sc":1,"op":2,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"0":"40, 48","1":"44, 49","2":"5, 13, 23","3":"53","4":"50","6":"2"}},{"t":"const","label":"Article I, Section 8, Clause 10","text":"To define and punish Piracies and Felonies committed on the high Seas, and Offences against the Law of Nations;","by":{"0":"40"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"0":"17"}},{"t":"usc","label":"18 U.S.C. § 1595","url":"https://www.law.cornell.edu/uscode/text/18/1595","subs":["(a)"],"stext":{"head":"§1595. Civil remedy","paras":[[0,"(a) An individual who is a victim of a violation of this chapter may bring a civil action against the perpetrator (or whoever knowingly benefits, or attempts or conspires to benefit, financially or by receiving anything of value from participation in a venture which that person knew or should have known has engaged in an act in violation of this chapter) in an appropriate district court of the United States and may recover damages and reasonable attorneys fees."],[0,"(b)(1) Any civil action filed under subsection (a) shall be stayed during the pendency of any criminal action arising out of the same occurrence in which the claimant is the victim."],[0,"(2) In this subsection, a \"criminal action\" includes investigation and prosecution and is pending until final adjudication in the trial court."],[0,"(c) No action may be maintained under subsection (a) unless it is commenced not later than the later of—"],[1,"(1) 10 years after the cause of action arose; or"],[1,"(2) 10 years after the victim reaches 18 years of age, if the victim was a minor at the time of the alleged offense."],[0,"(d) In any case in which the attorney general of a State has reason to believe that an interest of the residents of that State has been or is threatened or adversely affected by any person who violates section 1591, the attorney general of the State, as parens patriae, may bring a civil action against such person on behalf of the residents of the State in an appropriate district court of the United States to obtain appropriate relief."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1595?type=usc&year=mostrecent&link-type=html"},"head":"§1595. Civil remedy","tname":"Crimes and Criminal Procedure","by":{"0":"44","1":"47, 49","3":"28, passim","4":"26","5":"22"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"stext":{"head":"§1254. Courts of appeals; certiorari; certified questions","paras":[[0,"Cases in the courts of appeals may be reviewed by the Supreme Court by the following methods:"],[1,"(1) By writ of certiorari granted upon the petition of any party to any civil or criminal case, before or after rendition of judgment or decree;"],[1,"(2) By certification at any time by a court of appeals of any question of law in any civil or criminal case as to which instructions are desired, and upon such certification the Supreme Court may give binding instructions or require the entire record to be sent up for decision of the entire matter in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1254?type=usc&year=mostrecent&link-type=html"},"head":"§1254. Courts of appeals; certiorari; certified questions","tname":"Judiciary and Judicial Procedure","by":{"0":"5","1":"1"}},{"t":"usc","label":"28 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/28/1350","subs":["(note)"],"stext":{"head":"§1350. Alien's action for tort","paras":[[0,"The district courts shall have original jurisdiction of any civil action by an alien for a tort only, committed in violation of the law of nations or a treaty of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1350?type=usc&year=mostrecent&link-type=html"},"op":11,"head":"§1350. Alien's action for tort","tname":"Judiciary and Judicial Procedure","by":{"0":"passim, 12, 42, 43, 50","1":"passim, 15, 16, 21, 47, 48, 49","3":"passim","4":"passim","5":"16","6":"21"}},{"t":"usc","label":"18 U.S.C. § 2333","url":"https://www.law.cornell.edu/uscode/text/18/2333","stext":{"head":"§2333. Civil remedies","paras":[[0,"(a) Action and Jurisdiction.—Any national of the United States injured in his or her person, property, or business by reason of an act of international terrorism, or his or her estate, survivors, or heirs, may sue therefor in any appropriate district court of the United States and shall recover threefold the damages he or she sustains and the cost of the suit, including attorney's fees."],[0,"(b) Estoppel Under United States Law.—A final judgment or decree rendered in favor of the United States in any criminal proceeding under section 1116, 1201, 1203, or 2332 of this title or section 46314, 46502, 46505, or 46506 of title 49 shall estop the defendant from denying the essential allegations of the criminal offense in any subsequent civil proceeding under this section."],[0,"(c) Estoppel Under Foreign Law.—A final judgment or decree rendered in favor of any foreign state in any criminal proceeding shall, to the extent that such judgment or decree may be accorded full faith and credit under the law of the United States, estop the defendant from denying the essential allegations of the criminal offense in any subsequent civil proceeding under this section."],[0,"(d) Liability.—"],[1,"(1) Definition.—In this subsection, the term \"person\" has the meaning given the term in section 1 of title 1."],[1,"(2) Liability.—In an action under subsection (a) for an injury arising from an act of international terrorism committed, planned, or authorized by an organization that had been designated as a foreign terrorist organization under section 219 of the Immigration and Nationality Act (8 U.S.C. 1189), as of the date on which such act of international terrorism was committed, planned, or authorized, liability may be asserted as to any person who aids and abets, by knowingly providing substantial assistance, or who conspires with the person who committed such an act of international terrorism."],[0,"(e) Use of Blocked Assets to Satisfy Judgments of U.S. Nationals.—For purposes of section 201 of the Terrorism Risk Insurance Act of 2002 (28 U.S.C. 1610 note), in any action in which a national of the United States has obtained a judgment against a terrorist party pursuant to this section, the term \"blocked asset\" shall include any asset of that terrorist party (including the blocked assets of any agency or instrumentality of that party) seized or frozen by the United States under section 805(b) of the Foreign Narcotics Kingpin Designation Act (21 U.S.C. 1904(b))."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2333?type=usc&year=mostrecent&link-type=html"},"head":"§2333. Civil remedies","tname":"Crimes and Criminal Procedure","by":{"0":"43","1":"21, 47, 49"}},{"t":"usc","label":"18 U.S.C. § 1581","url":"https://www.law.cornell.edu/uscode/text/18/1581","stext":{"head":"§1581. Peonage; obstructing enforcement","paras":[[0,"(a) Whoever holds or returns any person to a condition of peonage, or arrests any person with the intent of placing him in or returning him to a condition of peonage, shall be fined under this title or imprisoned not more than 20 years, or both. If death results from the violation of this section, or if the violation includes kidnapping or an attempt to kidnap, aggravated sexual abuse or the attempt to commit aggravated sexual abuse, or an attempt to kill, the defendant shall be fined under this title or imprisoned for any term of years or life, or both."],[0,"(b) Whoever obstructs, or attempts to obstruct, or in any way interferes with or prevents the enforcement of this section, shall be liable to the penalties prescribed in subsection (a)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1581?type=usc&year=mostrecent&link-type=html"},"head":"§1581. Peonage; obstructing enforcement","tname":"Crimes and Criminal Procedure","by":{"0":"43, 44","1":"49","5":"4"}},{"t":"case","label":"Adhikari v. Kellogg Brown & Root, Inc.","cite":"845 F.3d 184","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/845/184/","by":{"1":"34"}},{"t":"case","label":"Baloco v. Drummond Co.","cite":"767 F.3d 1229","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/767/1229/","sum":"Holding that domestic decision-making, including decision to provide funding to paramilitary groups in a foreign country, did not displace presumption against extraterritoriality.","sumSrc":"brief:1","by":{"1":"34"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Federal Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"ar":2,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"1":"15, 20, 44","2":"5, 12","3":"53","4":"50"}},{"t":"case","label":"Cardona v. Chiquita Brands Int’l, Inc.","cite":"760 F.3d 1185","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/760/1185/","by":{"1":"34"}},{"t":"case","label":"Corrie v. Caterpillar, Inc.","cite":"403 F. Supp. 2d 1019","y":2005,"court":"W.D. Wash.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/403/1019/","by":{"1":"38"}},{"t":"case","label":"Doe v. Drummond Co.","cite":"782 F.3d 576","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/782/576/","sum":"Holding that “the domestic location of the [defendant’s] decision-making alleged in general terms * * * does not outweigh the extraterritorial location of the rest of Plaintiffs’ claims.”.","sumSrc":"brief:1","by":{"1":"34","3":"23","4":"22"}},{"t":"case","label":"Hefferman v. Bass","cite":"467 F.3d 596","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/467/596/","by":{"1":"31"}},{"t":"case","label":"Licci by Licci v. Lebanese Canadian Bank, SAL","cite":"834 F.3d 201","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/834/201/","by":{"1":"34"}},{"t":"case","label":"Mastafa v. Chevron Corp.","cite":"770 F.3d 170","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/770/170/","by":{"1":"34","3":"23","4":"22","5":"12"}},{"t":"case","label":"Pinter v. Dahl","cite":"486 U.S. 622","y":1988,"id":"1987/86-805","sc":1,"sum":"Petitioner Pinter, an oil and gas producer and registered securities dealer, sold unregistered securities consisting of fractional undivided interests in oil and gas leases to respondent Dahl, a real estate broker and investor who was experienced in oil and gas ventures. Dahl touted the venture to the other respondents-his friends, family, and business associates -and assisted them in completing subscription …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"by":{"1":"27, 30, 32"}},{"t":"usc","label":"18 U.S.C. § 1091","url":"https://www.law.cornell.edu/uscode/text/18/1091","by":{"1":"49"}},{"t":"usc","label":"18 U.S.C. § 1596","url":"https://www.law.cornell.edu/uscode/text/18/1596","subs":["(a)"],"stext":{"head":"§1596. Additional jurisdiction in certain trafficking offenses","paras":[[0,"(a) In General.—In addition to any domestic or extra-territorial jurisdiction otherwise provided by law, the courts of the United States have extra-territorial jurisdiction over any offense (or any attempt or conspiracy to commit an offense) under section 1581, 1583, 1584, 1589, 1590, or 1591 if—"],[1,"(1) an alleged offender is a national of the United States or an alien lawfully admitted for permanent residence (as those terms are defined in section 101 of the Immigration and Nationality Act (8 U.S.C. 1101)); or"],[1,"(2) an alleged offender is present in the United States, irrespective of the nationality of the alleged offender."],[0,"(b) Limitation on Prosecutions of Offenses Prosecuted in Other Countries.—No prosecution may be commenced against a person under this section if a foreign government, in accordance with jurisdiction recognized by the United States, has prosecuted or is prosecuting such person for the conduct constituting such offense, except upon the approval of the Attorney General or the Deputy Attorney General (or a person acting in either such capacity), which function of approval may not be delegated."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1596?type=usc&year=mostrecent&link-type=html"},"head":"§1596. Additional jurisdiction in certain trafficking offenses","tname":"Crimes and Criminal Procedure","by":{"1":"49","3":"28","4":"27","5":"5"}},{"t":"usc","label":"18 U.S.C. § 2331-2339D","url":"https://www.law.cornell.edu/uscode/text/18/2331-2339D","by":{"1":"49"}},{"t":"usc","label":"18 U.S.C. § 2340A","url":"https://www.law.cornell.edu/uscode/text/18/2340A","by":{"1":"49"}},{"t":"usc","label":"19 U.S.C. § 1307","url":"https://www.law.cornell.edu/uscode/text/19/1307","by":{"1":"49"}},{"t":"case","label":"Bell Atl. Corp. v. Twombly","cite":"550 U.S. 544","y":2007,"id":"2006/05-1126","sc":1,"sum":"The Court ruled 7-2 that a plaintiff claiming a Section 1 violation must also allege facts that, if true, would suggest a conspiratorial agreement.","sumSrc":"Oyez","by":{"2":"9, 31","6":"16"}},{"t":"case","label":"Crosby v. National Foreign Trade Council","cite":"530 U.S. 363","y":2000,"id":"1999/99-474","sc":1,"sum":"The Court held that \"the state Act is preempted, and its application unconstitutional, under the Supremacy Clause.\" Justice Souter wrote for the Court that Massachusetts' law created an obstacle to the President's discretion to control economic sanctions against Burma, interfered with Congress's intention to limit economic pressure against the Burmese Government, and was at odds with the President's authority to speak for the United States among the world's nations to develop a comprehensive, multilateral Burma strategy.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Eastern Trading Co. v. Refco, Inc.","cite":"229 F.3d 617","y":2000,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/229/617/","by":{"2":"29"}},{"t":"case","label":"Halberstam v. Welch","cite":"705 F.2d 472","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/705/472/","by":{"2":"29"}},{"t":"case","label":"Hamdan v. Rumsfeld","cite":"548 U.S. 557","y":2006,"id":"2005/05-184","sc":1,"ar":1,"sum":"The Court found that the rights given by the Geneva Convention to prisoners of war could be enforced by federal court.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Hernandez v. Mesa","cite":"140 S. Ct. 735","y":2020,"id":"2019/17-1678","sc":1,"ar":1,"sum":"The Court held that the family of a Mexican teenager who was killed by a U.S. Border Patrol agent in a cross-border shooting cannot sue the agent for damages under the U.S. Constitution.","sumSrc":"Oyez","by":{"2":"18, 20","5":"13, 22","6":"1, 7"}},{"t":"case","label":"Rosemond v. United States","cite":"572 US. 65","y":2014,"url":"https://www.courtlistener.com/c/US./572/65/","sum":"Concluding that the federal aidingand-abetting statute “reflects a centuries-old view of culpability: that a person may be responsible for a crime he has not personally carried out if he helps another to complete its commission”.","sumSrc":"brief:2","by":{"2":"28"}},{"t":"case","label":"Sarei v. Rio Tinto, PLC","cite":"671 F.3d 736","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/671/736/","sum":"Concluding the prohibition against genocide extends to corporations.","sumSrc":"brief:4","by":{"2":"23","3":"36-37","4":"35"}},{"t":"case","label":"United States v. Johnson","cite":"319 U.S. 503","y":1943,"id":"scdb/1942-090","sc":1,"sum":"1. Under Jud. Code § 284, a grand jury can be authorized to sit beyond the term of court at which it was organized only to finish investigations begun during that term.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"United States v. Smith","cite":"198 F.3d 377","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/198/377/","by":{"2":"28"}},{"t":"case","label":"WesternGeco LLC v. ION Geophysical Corp.","cite":"138 S. Ct. 2129","y":2018,"id":"2017/16-1011","sc":1,"sum":"The Court held that WesternGeco’s award for lost profits was a permissible domestic application of § 284 of the Patent Act.","sumSrc":"Oyez","by":{"2":"26, 27","3":"21","4":"20","6":"5, 6, 14"}},{"t":"reg","label":"Exec. Order No. 13,928, 85 Fed. Reg. 36,139","url":"https://www.govinfo.gov/link/fr/85/36139","by":{"2":"29"}},{"t":"case","label":"Al Shimari v. CACI Premier Tech.","cite":"758 F.3d 516","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/758/516/","by":{"3":"23","4":"22"}},{"t":"case","label":"Argentine Republic v. Amerada Hess Shipping Corp.","cite":"488 U.S. 428","y":1989,"id":"1988/87-1372","sc":1,"sum":"The FSIA provides the sole basis for obtaining jurisdiction over a foreign state in United States courts, and the District Court correctly dismissed the action because the FSIA did not authorize jurisdiction over petitioner under the facts of this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"36, 39","4":"34, 37"}},{"t":"case","label":"Banco Nacional de Cuba v. Sabbatino","cite":"376 U.S. 398","y":1964,"id":"1963/16","sc":1,"sum":"The Supreme Court held that it will not decide the validity of a decree by a foreign government absent a treaty or other agreement. It did not matter that the taking violated customary international law. The majority noted that a judicial decision on this issue without a treaty would strain U.S.-Cuba relations.","sumSrc":"Oyez","by":{"3":"42","4":"40"}},{"t":"case","label":"Balt. & Potomac R.R. Co. v. Fifth Baptist Church","cite":"108 U.S. 317","y":1883,"id":"scdb/1882-217","sc":1,"op":1,"sum":"Corporation — ^Damages—Legislative Grant — Nuisance.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"39","4":"37"}},{"t":"case","label":"Barrientos v. CoreCivic, Inc.","cite":"951 F.3d 1269","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/951/1269/","by":{"3":"51","4":"48"}},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"sum":"1. Where the complaint seeks recovery squarely on the ground of violation of plaintiffs' rights under the Fourth and Fifth Amendments, a federal district court has jurisdiction of a suit against agents of the Federal Government to recover damages in excess of $3,000 alleged to have been suffered by the plaintiffs as a result of such violations-even though neither the Constitution nor the Congress has provided for …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"35","4":"39"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"3":"34","4":"34"}},{"t":"case","label":"Daimler AG v. Bauman","cite":"571 U.S. 117","y":2014,"id":"2013/11-965","sc":1,"sum":"The Court held the judiciary did not have jurisdiction over DaimlerChrysler AG in California because the conduct in question was not in the state.","sumSrc":"Oyez","by":{"3":"14","4":"14"}},{"t":"case","label":"Doe v. Nestlé, S.A.","cite":"929 F.3d 623","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/929/623/","op":1,"by":{"3":"passim","4":"passim"}},{"t":"case","label":"Doe I v. Nestlé USA, Inc.","cite":"766 F.3d 1013","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/766/1013/","by":{"3":"passim","4":"passim"}},{"t":"case","label":"Fagan v. Deutsche Bundesbank","cite":"438 F. Supp. 2d 376","y":2006,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/438/376/","by":{"3":"31","4":"30"}},{"t":"case","label":"Flomo v. Firestone Nat. Rubber Co.","cite":"643 F.3d 1013","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/643/1013/","by":{"3":"36","4":"35"}},{"t":"case","label":"Impression Products, Inc. v. Lexmark International, Inc.","cite":"137 S. Ct. 1523","y":2017,"id":"2016/15-1189","sc":1,"sum":"The Court determined that a patentee’s decision to sell an item exhausts all of its patent rights in that item, even if the e patentee purports to impose post-sale restrictions, and regardless of whether the sale occurs domestically or internationally.","sumSrc":"Oyez","by":{"3":"21","4":"21","5":"3","6":"6"}},{"t":"case","label":"Jansen v. The Vrow Christina Magdalena","cite":"13 F. Cas. 356","y":1794,"court":"D.S.C.","url":"https://www.courtlistener.com/c/F.%20Cas./13/356/","op":1,"sum":"Recognizing ATS claim would be a basis for jurisdiction for acts outside of U.S. territory, on high seas.","sumSrc":"brief:3","by":{"3":"26","4":"25"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"sum":"The Court found that there is not geographical restriction on the \"first sale\" copyright doctrine.","sumSrc":"Oyez","by":{"3":"21","4":"20","6":"6"}},{"t":"case","label":"Mayor v. Turner","cite":"98 Eng. Rep. 980","url":"https://www.courtlistener.com/c/Eng.%20Rep./98/980/","sum":"Holding a corporation liable for failing to repair creek in 1774.","sumSrc":"brief:3","by":{"3":"38","4":"37"}},{"t":"case","label":"Meyer v. Holley","cite":"537 U.S. 280","y":2003,"id":"2002/01-1120","sc":1,"sum":"The Court held that the FHA imposes liability without fault upon the employer in accordance with traditional agency principles. In other words, the FHA normally imposes vicarious liability upon the corporation, but not upon its officers or owners.","sumSrc":"Oyez","by":{"3":"38, 39","4":"36, 37","5":"16"}},{"t":"case","label":"Oceanic Steam Nav. Co. v. Mellor","cite":"233 U.S. 718","y":1914,"id":"scdb/1913-120","sc":1,"sum":"This case falls within the general proposition that a. foreign ship may-resort to the courts of the United States for a limitation of liability undér § 4283, Rey. Stat. The Scotland, 105 U. S. 24.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"39","4":"37"}},{"t":"case","label":"Panama R. Co. v. Napier Shipping Co.","cite":"166 U.S. 280","y":1897,"id":"scdb/1896-139","sc":1,"sum":"The libel in this case was dismissed by the tri?.l court. The judgment of that court was reversed by the Court of Appeals, and the case was remanded for assessment of damages. After assessment and decree it was again taken to the Court of Appeals, where the decree of assessment was affirmed, whereupon a writ of certiorari from this court was granted. Held, that, upon such writ, the entire case was before this court …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"39","4":"37-38"}},{"t":"case","label":"Ricchio v. McLean","cite":"853 F.3d 553","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/853/553/","by":{"3":"27","4":"26"}},{"t":"case","label":"Romero v. Drummond Co.","cite":"552 F.3d 1303","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/552/1303/","by":{"3":"37","4":"35"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"40","4":"38"}},{"t":"case","label":"Staub v. Proctor Hosp.","cite":"562 U.S. 411","y":2001,"id":"2010/09-400","sc":1,"sum":"The Court held that an employer may be found liable for the discriminatory acts of supervisors, who do not themselves make employment decisions but do influence the employment decision-makers.","sumSrc":"Oyez","by":{"3":"38","4":"36","5":"16"}},{"t":"case","label":"United States v. Bowman","cite":"260 U.S. 94","y":1922,"id":"scdb/1922-015","sc":1,"sum":"1. A criminal statute dealing w-ith acts that are directly injurious to the Government and are capable of perpetration without regard to particular locality, and subjecting all who commit them to punishment, is to be construed as applicable to citizens of the United States upon the high seas or in a foreign country, though there be no express declaration to that effect.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"21","4":"20","5":"4","6":"6"}},{"t":"usc","label":"22 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/22/7101","stext":{"head":"§7101. Purposes and findings","paras":[[0,"(a) Purposes"],[0,"The purposes of this chapter are to combat trafficking in persons, a contemporary manifestation of slavery whose victims are predominantly women and children, to ensure just and effective punishment of traffickers, and to protect their victims."],[0,"(b) Findings"],[0,"Congress finds that:"],[1,"(1) As the 21st century begins, the degrading institution of slavery continues throughout the world. Trafficking in persons is a modern form of slavery, and it is the largest manifestation of slavery today. At least 700,000 persons annually, primarily women and children, are trafficked within or across international borders. Approximately 50,000 women and children are trafficked into the United States each year."],[1,"(2) Many of these persons are trafficked into the international sex trade, often by force, fraud, or coercion. The sex industry has rapidly expanded over the past several decades. It involves sexual exploitation of persons, predominantly women and girls, involving activities related to prostitution, pornography, sex tourism, and other commercial sexual services. The low status of women in many parts of the world has contributed to a burgeoning of the trafficking industry."],[1,"(3) Trafficking in persons is not limited to the sex industry. This growing transnational crime also includes forced labor and involves significant violations of labor, public health, and human rights standards worldwide."],[1,"(4) Traffickers primarily target women and girls, who are disproportionately affected by poverty, the lack of access to education, chronic unemployment, discrimination, and the lack of economic opportunities in countries of origin. Traffickers lure women and girls into their networks through false promises of decent working conditions at relatively good pay as nannies, maids, dancers, factory workers, restaurant workers, sales clerks, or models. Traffickers also buy children from poor families and sell them into prostitution or into various types of forced or bonded labor."],[1,"(5) Traffickers often transport victims from their home communities to unfamiliar destinations, including foreign countries away from family and friends, religious institutions, and other sources of protection and support, leaving the victims defenseless and vulnerable."],[1,"(6) Victims are often forced through physical violence to engage in sex acts or perform slavery-like labor. Such force includes rape and other forms of sexual abuse, torture, starvation, imprisonment, threats, psychological abuse, and coercion."],[1,"(7) Traffickers often make representations to their victims that physical harm may occur to them or others should the victim escape or attempt to escape. Such representations can have the same coercive effects on victims as direct threats to inflict such harm."],[1,"(8) Trafficking in persons is increasingly perpetrated by organized, sophisticated criminal enterprises. Such trafficking is the fastest growing source of profits for organized criminal enterprises worldwide. Profits from the trafficking industry contribute to the expansion of organized crime in the United States and worldwide. Trafficking in persons is often aided by official corruption in countries of origin, transit, and destination, thereby threatening the rule of law."],[1,"(9) Trafficking includes all the elements of the crime of forcible rape when it involves the involuntary participation of another person in sex acts by means of fraud, force, or coercion."],[1,"(10) Trafficking also involves violations of other laws, including labor and immigration codes and laws against kidnapping, slavery, false imprisonment, assault, battery, pandering, fraud, and extortion."],[1,"(11) Trafficking exposes victims to serious health risks. Women and children trafficked in the sex industry are exposed to deadly diseases, including HIV and AIDS. Trafficking victims are sometimes worked or physically brutalized to death."],[1,"(12) Trafficking in persons substantially affects interstate and foreign commerce. Trafficking for such purposes as involuntary servitude, peonage, and other forms of forced labor has an impact on the nationwide employment network and labor market. Within the context of slavery, servitude, and labor or services which are obtained or maintained through coercive conduct that amounts to a condition of servitude, victims are subjected to a range of violations."],[1,"(13) Involuntary servitude statutes are intended to reach cases in which persons are held in a condition of servitude through nonviolent coercion. In United States v. Kozminski, 487 U.S. 931 (1988), the Supreme Court found that section 1584 of title 18, should be narrowly interpreted, absent a definition of involuntary servitude by Congress. As a result, that section was interpreted to criminalize only servitude that is brought about through use or threatened use of physical or legal coercion, and to exclude other conduct that can have the same purpose and effect."],[1,"(14) Existing legislation and law enforcement in the United States and other countries are inadequate to deter trafficking and bring traffickers to justice, failing to reflect the gravity of the offenses involved. No comprehensive law exists in the United States that penalizes the range of offenses involved in the trafficking scheme. Instead, even the most brutal instances of trafficking in the sex industry are often punished under laws that also apply to lesser offenses, so that traffickers typically escape deserved punishment."],[1,"(15) In the United States, the seriousness of this crime and its components is not reflected in current sentencing guidelines, resulting in weak penalties for convicted traffickers."],[1,"(16) In some countries, enforcement against traffickers is also hindered by official indifference, by corruption, and sometimes even by official participation in trafficking."],[1,"(17) Existing laws often fail to protect victims of trafficking, and because victims are often illegal immigrants in the destination country, they are repeatedly punished more harshly than the traffickers themselves."],[1,"(18) Additionally, adequate services and facilities do not exist to meet victims' needs regarding health care, housing, education, and legal assistance, which safely reintegrate trafficking victims into their home countries."],[1,"(19) Victims of severe forms of trafficking should not be inappropriately incarcerated, fined, or otherwise penalized solely for unlawful acts committed as a direct result of being trafficked, such as using false documents, entering the country without documentation, or working without documentation."],[1,"(20) Because victims of trafficking are frequently unfamiliar with the laws, cultures, and languages of the countries into which they have been trafficked, because they are often subjected to coercion and intimidation including physical detention and debt bondage, and because they often fear retribution and forcible removal to countries in which they will face retribution or other hardship, these victims often find it difficult or impossible to report the crimes committed against them or to assist in the investigation and prosecution of such crimes."],[1,"(21) Trafficking of persons is an evil requiring concerted and vigorous action by countries of origin, transit or destination, and by international organizations."],[1,"(22) One of the founding documents of the United States, the Declaration of Independence, recognizes the inherent dignity and worth of all people. It states that all men are created equal and that they are endowed by their Creator with certain unalienable rights. The right to be free from slavery and involuntary servitude is among those unalienable rights. Acknowledging this fact, the United States outlawed slavery and involuntary servitude in 1865, recognizing them as evil institutions that must be abolished. Current practices of sexual slavery and trafficking of women and children are similarly abhorrent to the principles upon which the United States was founded."],[1,"(23) The United States and the international community agree that trafficking in persons involves grave violations of human rights and is a matter of pressing international concern. The international community has repeatedly condemned slavery and involuntary servitude, violence against women, and other elements of trafficking, through declarations, treaties, and United Nations resolutions and reports, including the Universal Declaration of Human Rights; the 1956 Supplementary Convention on the Abolition of Slavery, the Slave Trade, and Institutions and Practices Similar to Slavery; the 1948 American Declaration on the Rights and Duties of Man; the 1957 Abolition of Forced Labor Convention; the International Covenant on Civil and Political Rights; the Convention Against Torture and Other Cruel, Inhuman or Degrading Treatment or Punishment; United Nations General Assembly Resolutions 50/167, 51/66, and 52/98; the Final Report of the World Congress against Sexual Exploitation of Children (Stockholm, 1996); the Fourth World Conference on Women (Beijing, 1995); and the 1991 Moscow Document of the Organization for Security and Cooperation in Europe."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/7101?type=usc&year=mostrecent&link-type=html"},"head":"§7101. Purposes and findings","tname":"Foreign Relations and Intercourse","by":{"3":"13","4":"13"}},{"t":"case","label":"Brief for Joseph E. Stiglitz as Amicus Curiae Supporting Petitioners, Mohamad v. Palestinian Auth.","cite":"132 S. Ct. 994","y":2012,"url":"https://www.courtlistener.com/c/S.%20Ct./132/994/","sc":1,"op":1,"by":{"3":"32","4":"31"}},{"t":"usc","label":"18 U.S.C. § 1589","url":"https://www.law.cornell.edu/uscode/text/18/1589","by":{"4":"26"}},{"t":"case","label":"Foman v. Davis","cite":"371 U.S. 178","y":1962,"id":"1962/41","sc":1,"sum":"A Federal District Court dismissed petitioner's complaint in a civil action for failure to state a claim upon which relief might be granted. Petitioner promptly moved to vacate the judgment and amend the complaint so as to state an alternative theory for recovery. Before the Court ruled on those motions, petitioner filed notice of appeal from the judgment of dismissal. Subsequently, the District Court denied the …","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"12"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"sum":"The Court held that the court system cannot disregard the location of a corporation's principal place of business in a multi-state lawsuit.","sumSrc":"Oyez","by":{"5":"12"}},{"t":"case","label":"Int’l Paper Co. v. Ouellette","cite":"479 U.S. 481","y":1987,"id":"1986/85-1233","sc":1,"sum":"The Clean Water Act (Act) prohibits the discharge of effluents into navigable waters unless the point source has obtained a permit from the Environmental Protection Agency (EPA). The Act also allows the State in which the point source is located (the \"source State\") to impose more stringent discharge limitations than the federal ones, and even to administer its own permit program if certain requirements are met. In …","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"13"}},{"t":"case","label":"Nevsun Res. Ltd. v. Araya","cite":"2020 SCC 5","url":"https://www.courtlistener.com/c/SCC/2020/5/","by":{"5":"20"}},{"t":"case","label":"Place v. Norwich & N.Y. Transp. Co.","cite":"118 U.S. 468","y":1886,"id":"scdb/1885-277","sc":1,"sum":"In a ease of collision occasioned by the negligence of the officers or hands of one of the vessels, without any neglect, privity, or knowledge of her owner, and where said vessel took fire and sank with loss of cargo, and never completed her voyage nor earned any freight, but was afterwards raised and repaired, and was then libelled and seized on behalf of the owners of her cargo, and claimed and bonded at her then …","sumSrc":"Headnote (U.S. Reports)","by":{"5":"17"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"5":"17"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","subs":["(b)"],"by":{"5":"17"}},{"t":"case","label":"City of Milwaukee v. Illinois","cite":"451 U.S. 304","y":1981,"id":"1980/79-408","sc":1,"sum":"In original proceedings brought by respondent State of Illinois, alleging that petitioners-the city of Milwaukee, its Sewerage Commission, and Milwaukee County's Metropolitan Sewerage Commission-and other Wisconsin cities were polluting Lake Michigan because of overflows of untreated sewage from their sewer systems and discharges of inadequately treated sewage from their treatment plants, this Court recognized the …","sumSrc":"Syllabus (U.S. Reports)","by":{"6":"2"}},{"t":"case","label":"Glass v. The Sloop Betsey","cite":"3 U.S. 6","y":1794,"id":"scdb/1794-002","sc":1,"by":{"6":"10"}},{"t":"case","label":"Talbot v. Jansen","cite":"3 U.S. 133","y":1795,"id":"scdb/1795-006","sc":1,"ar":2,"sum":"THIS was a Writ of Error, in the nature of an Appeal, from the Circuit Court for the District of South Carolina; and the following circumstances appeared upon the pleadings:— A Libel was filed against Edward Ballard, Captain of an armed vessel, called L' Ami de la Liberte, on the Admiralty side of the District Court of South Carolina, in June, 1794, by Joost Janson, late master of the Brigantine Magdalena (then …","sumSrc":"Headnote (U.S. Reports)","by":{"6":"10"}},{"t":"case","label":"Tel-Oren v. Libyan Arab Republic","cite":"726 F.2d 774","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/726/774/","by":{"6":"21"}},{"t":"usc","label":"18 U.S.C. § 1595-96","url":"https://www.law.cornell.edu/uscode/text/18/1595-96","by":{"6":"2, 21, 22, 23"}}]};